/* ==========================================================================
   QUIET IRIS  ·  a calm ship intelligence
   Structural idea: THE SPINE AND THE LENS.
   One continuous vertical signal spine runs down every conversation; each
   message docks to it through a circular lens node (the avatar in aperture
   rings) and reads as a borderless log slab with a readout line. Everything
   that is "the machine looking" is a circle; everything else is a precise
   3px-radius instrument plate; rulers (fine tick scales) edge the top bar,
   the console and every Home module. Red-amber is used only for the lens.
   ========================================================================== */

:root {
  --mari-tokens-version: 1;

  /* ---- shape + type ---- */
  --radius: 0.1875rem;
  --hal-r: 3px;
  --mari-font-ui: "Iris Text", "Inter", system-ui, sans-serif;
  --mari-font-heading: "Iris Display", "Iris Text", "Inter", system-ui, sans-serif;
  --mari-font-chat: "Iris Text", "Inter", system-ui, sans-serif;
  --hal-mono: "Iris Mono", ui-monospace, "SFMono-Regular", Menlo, monospace;

  /* ---- reading ---- */
  --mari-chat-column: 56rem;
  --mari-message-measure: 34em;
  --mari-pinned-speaker-bleed: 0;
  --ov-cs-pill-radius: 3px;
  --mari-chat-line-height: 1.68;
  --mari-chat-font-size: 16px;
  --mari-paragraph-gap: 0.8em;
  --mari-dialogue-weight: 400;
  --mari-text-outline: 0;
  --mari-pinned-speaker: on;
  --mari-phone-avatar: hidden;
  --mari-mini-avatar-size: 1.25rem;
  --mari-vn-fade: 1.5rem;
  --mari-min-ui-text: 11px;
  --mari-composer-placeholder: "Speak. I am listening.";

  /* ---- selection: neutral, the lens marks it ---- */
  --mari-selected-tint: var(--foreground);
  --mari-chat-row-art-opacity: 0;

  /* ---- motion: none constant, only the lens breathes ---- */
  --mari-ambient: none;

  /* ---- Home ---- */
  --mari-home-art: none;
  --mari-home-widget-radius: var(--hal-r);
  --mari-home-widget-border-width: 1px;
  --mari-home-widget-title-font: "Iris Display", "Iris Text", system-ui, sans-serif;
  --mari-home-widget-title-size: 1.45rem;
  --mari-home-widget-eyebrow-size: 0.66rem;
  --mari-home-widget-glow: none;
  --mari-professor-sprite-scale: 0.92;

  /* ---- weather: seen through the viewport, thin and quiet ---- */
  --mari-weather-style: smooth;
  --mari-weather-amount: 0.55;
  --mari-weather-speed: 0.8;
  --mari-weather-strength: 0.8;
  --mari-weather-tint-strength: 0.35;
  --mari-weather-rain-length: 1.7;
  --mari-weather-snow-shape: round;
  --mari-weather-snow-size: 0.7;
  --mari-weather-dust-size: 0.6;
  --mari-weather-star-size: 0.7;
  --mari-weather-lightning-bolt: none;
  --mari-weather-sun: none;
}

/* ===================== NIGHT · the black ship ===================== */
:root[data-theme="dark"] {
  --hal-void: #060607;
  --hal-g0: #0b0b0d;
  --hal-g1: #111214;
  --hal-g2: #17181b;
  --hal-g3: #202226;
  --hal-line: #2c2e33;
  --hal-line-soft: #1e2023;
  --hal-text: #e8e6e1;
  --hal-muted: #a6a5a0;
  --hal-dim: #85868a;
  --hal-lens: #ff6a3d;
  --hal-lens-text: #ff8a66;
  --hal-spine: rgba(255, 255, 255, 0.18);
  --hal-switch-off: #1b1c1f;
  --hal-knob: #5b5e64;
  --hal-iris: url("theme:iris-night.svg");
  --hal-iris-key: url("theme:iris-key-night.svg");
  --hal-amber: #ffae62;
  --hal-slab: #101113;
