  --hal-shadow: 0 22px 48px -22px rgba(0, 0, 0, 0.85);
  --hal-tick: rgba(255, 255, 255, 0.11);
  --hal-tick-strong: rgba(255, 255, 255, 0.2);
  --hal-brushed: url("theme:brushed-night.webp");

  --background: #0b0b0d;
  --foreground: #e8e6e1;
  --card: #111214;
  --card-foreground: #e8e6e1;
  --popover: #121315;
  --popover-foreground: #e8e6e1;
  --primary: #dedbd4;
  --primary-foreground: #0c0c0e;
  --secondary: #1b1c1f;
  --secondary-foreground: #e8e6e1;
  --muted: #18191c;
  --muted-foreground: #a6a5a0;
  --accent: #202226;
  --accent-foreground: #e8e6e1;
  --destructive: #e0442a;
  --destructive-foreground: #fff6f2;
  --border: #2c2e33;
  --input: #2c2e33;
  --ring: #ff6a3d;
