  --mari-card-art-placeholder: radial-gradient(circle at 50% 44%, rgba(255, 75, 43, 0.85) 0 3%, rgba(255, 75, 43, 0.15) 6%, transparent 14%), radial-gradient(circle at 50% 44%, transparent 0 21%, #2c2e33 21.5% 22%, transparent 22.5%), linear-gradient(180deg, #16171a, #0b0b0d);
