  --input: #c6c8c9;
  --ring: #cf4a22;
  --sidebar: #f1f0ee;
  --sidebar-foreground: #15171a;
  --sidebar-border: #cfd4d7;
  --sidebar-accent: #e4e7e9;
  --sidebar-accent-foreground: #0f1113;

  --ov-line: #d9dadb;
  --ov-text: #15171a;
  --ov-muted: #4c5157;
  --ov-dim: #636970;
  --ov-accent: #1d2024;
  --ov-hover: #e6e9eb;
  --ov-active-bg: #dde1e4;
  --ov-mode-conversation: #3f6380;
  --ov-mode-roleplay: #7f6440;
  --ov-mode-game: #4a6e4b;
  --mari-mode-conversation: #3f6380;
  --mari-mode-roleplay: #7f6440;
  --mari-mode-game: #4a6e4b;
