  --mari-resource-characters: #7f6440;
  --mari-resource-personas: #8a5048;
  --mari-resource-lorebooks: #6b6250;
  --mari-resource-presets: #3f6380;
  --mari-resource-connections: #4a6e4b;
  --mari-resource-agents: #5b5784;
  --mari-resource-settings: #4c5157;
