/* ===================== BACKDROP · the research bay ===================== */
:root[data-theme] {
  --mari-app-backdrop-layers: var(--hal-bg) left center / cover no-repeat, var(--hal-g0);
}
@media (max-aspect-ratio: 4/5) {
  :root[data-theme] {
    --mari-app-backdrop-layers: var(--hal-bg-phone) center top / cover no-repeat, var(--hal-g0);
  }
}
/* weather reaches the bay only through the glass: the backdrop swaps to a version
   with rain, frost or fog on the viewport (wide screens; portrait keeps its bay) */
:root[data-theme="dark"]:is([data-mari-weather="rain"], [data-mari-weather="storm"]) { --hal-bg: url("theme:bg-night-rain.webp"); }
:root[data-theme="dark"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --hal-bg: url("theme:bg-night-snow.webp"); }
:root[data-theme="dark"][data-mari-weather="fog"] { --hal-bg: url("theme:bg-night-fog.webp"); }
:root[data-theme="light"]:is([data-mari-weather="rain"], [data-mari-weather="storm"]) { --hal-bg: url("theme:bg-day-rain.webp"); }
:root[data-theme="light"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --hal-bg: url("theme:bg-day-snow.webp"); }
:root[data-theme="light"][data-mari-weather="fog"] { --hal-bg: url("theme:bg-day-fog.webp"); }
/* portrait: the portrait bay swaps to its own painted weather version too */
:root[data-theme="dark"]:is([data-mari-weather="rain"], [data-mari-weather="storm"]) { --hal-bg-phone: url("theme:bg-phone-night-rain.webp"); }
:root[data-theme="dark"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --hal-bg-phone: url("theme:bg-phone-night-snow.webp"); }
:root[data-theme="dark"][data-mari-weather="fog"] { --hal-bg-phone: url("theme:bg-phone-night-fog.webp"); }
:root[data-theme="light"]:is([data-mari-weather="rain"], [data-mari-weather="storm"]) { --hal-bg-phone: url("theme:bg-phone-day-rain.webp"); }
:root[data-theme="light"]:is([data-mari-weather="snow"], [data-mari-weather="hail"]) { --hal-bg-phone: url("theme:bg-phone-day-snow.webp"); }
:root[data-theme="light"][data-mari-weather="fog"] { --hal-bg-phone: url("theme:bg-phone-day-fog.webp"); }
/* conversation lines have no plates, so the transcript stands on a veil */
:root[data-theme="dark"] [data-chat-mode="conversation"] .mari-messages-scroll {
  background-color: rgba(11, 11, 13, 0.82) !important;
}
:root[data-theme="light"] [data-chat-mode="conversation"] .mari-messages-scroll {
  background-color: rgba(235, 234, 231, 0.86) !important;
}

/* ===================== WEATHER · only through the viewport glass =====================
   The bay is indoors. When the theme's own bay is behind the chat (no chat picture,
   or the stock black one), the weather layer is cut to the viewport glass with a
   mask that is sized and placed exactly like the backdrop (cover, left centre on
   wide screens, centre top on portrait), measured against the whole window so it
   lines up at every aspect ratio. The canvas starts under the top bar and ends at
   the bottom of the window, so the mask is anchored to the bottom edge.
   A chat with its own picture keeps the app's own behaviour. */
:root[data-theme] {
  --hal-wx-glass: url("theme:wx-glass.svg");
}
img[data-mari-part="backdrop"][data-default-background] {
  opacity: 0 !important;
}
:root[data-mari-weather] .mari-chat-area:not(:has(> img[data-mari-part="backdrop"][src]:not([data-default-background]):not([style*="opacity: 0"]))) > [data-mari-part="weather"] {
  -webkit-mask-image: var(--hal-wx-glass);
  mask-image: var(--hal-wx-glass);
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  mask-mode: alpha;
  -webkit-mask-size: max(100vw, calc(100dvh * 1672 / 941)) auto;
  mask-size: max(100vw, calc(100dvh * 1672 / 941)) auto;
  -webkit-mask-position: left 0 bottom calc((100dvh - max(100dvh, calc(100vw * 941 / 1672))) / 2);
  mask-position: left 0 bottom calc((100dvh - max(100dvh, calc(100vw * 941 / 1672))) / 2);
}
@media (max-aspect-ratio: 4/5) {
  :root[data-mari-weather] .mari-chat-area:not(:has(> img[data-mari-part="backdrop"][src]:not([data-default-background]):not([style*="opacity: 0"]))) > [data-mari-part="weather"] {
    -webkit-mask-image: url("theme:wx-glass-phone.svg");
    mask-image: url("theme:wx-glass-phone.svg");
    -webkit-mask-size: max(100vw, calc(100dvh * 720 / 1560)) auto;
    mask-size: max(100vw, calc(100dvh * 720 / 1560)) auto;
    -webkit-mask-position: left calc((100vw - max(100vw, calc(100dvh * 720 / 1560))) / 2) bottom calc(100dvh - max(100dvh, calc(100vw * 1560 / 720)));
    mask-position: left calc((100vw - max(100vw, calc(100dvh * 720 / 1560))) / 2) bottom calc(100dvh - max(100dvh, calc(100vw * 1560 / 720)));
  }
}

/* ===================== global type ===================== */
body {
  font-family: var(--mari-font-ui);
  font-feature-settings: "cv11", "ss01";
  background: var(--hal-g0);
}
::selection {
  background: color-mix(in srgb, var(--hal-lens) 32%, transparent);
}
[data-mari-part="page-title"] {
  font-family: "Iris Display", var(--mari-font-ui);
  font-weight: 300;
  letter-spacing: 0.005em;
}

/* ===================== TOP BAR · brushed plate edged with a ruler ===================== */
:root {
  --mari-top-bar-plate-radius: var(--hal-r);
}
:root[data-theme] {
  --mari-top-bar-bg:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) left bottom / 100% 7px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) left bottom / 100% 4px no-repeat,
    linear-gradient(var(--hal-line), var(--hal-line)) left bottom / 100% 1px no-repeat,
    var(--hal-brushed) left top / 1024px 100% repeat-x,
    var(--hal-g1);
}
[data-mari-part="top-bar"] .ov-tab,
[data-mari-part="top-bar"] .ov-icon-btn,
[data-mari-part="top-bar"] .ov-text-btn {
  border-radius: var(--hal-r);
}
[data-mari-part="top-bar"] .ov-tab.is-on {
  box-shadow: inset 0 -2px 0 var(--hal-lens);
}
[data-mari-part="top-bar"] .ov-tab__label,
[data-mari-part="top-bar"] .ov-text-btn > span {
  letter-spacing: 0.02em;
}
[data-mari-part="top-bar"] .ov-text-btn small {
  font-family: var(--hal-mono);
  font-size: 0.68rem;
  letter-spacing: 0;
}

/* ===================== MESSAGES · the spine and the lens ===================== */
/* roleplay rows: everyone docks on the same left spine, like a ship's log */
.mari-roleplay-message-row {
  position: relative;
  margin-bottom: 0;
  padding-bottom: 1.15rem;
  gap: 1rem;
}
.mari-roleplay-message-row.mari-message-user {
  flex-direction: row;
  --mari-pinned-speaker-bg: var(--hal-slab-user);
}
.mari-roleplay-message-row {
  --mari-pinned-speaker-bg: var(--hal-slab);
}
[data-chat-mode="roleplay"] .mari-roleplay-message-row.mari-message-user > .mari-message-avatar {
  grid-column: 2;
}
.mari-roleplay-message-row .mari-roleplay-message-body {
  align-items: stretch;
  position: relative;
}
.mari-roleplay-message-row .mari-message-content {
  max-width: 34em;
}
.mari-roleplay-message-row > [data-mari-part="avatar"] {
  position: relative;
  align-self: stretch;
  width: 2.75rem;
  padding-top: 0.35rem;
}
/* the spine */
.mari-roleplay-message-row > [data-mari-part="avatar"]::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: -1.15rem;
  width: 1px;
  margin-left: -0.5px;
  background: var(--hal-spine);
}
/* the lens node: avatar inside aperture rings */
.mari-roleplay-message-row > [data-mari-part="avatar"] button {
  position: relative;
  z-index: 1;
  border-radius: 50%;
  --tw-ring-shadow: 0 0 #0000;
  box-shadow:
    0 0 0 1px var(--hal-line),
    0 0 0 4px var(--hal-g0),
    0 0 0 5px var(--hal-spine);
}
.mari-roleplay-message-row.mari-message-user > [data-mari-part="avatar"] button {
  width: 1.75rem;
  height: 1.75rem;
  margin-top: 0.4rem;
  filter: grayscale(0.35);
}
/* the newest reply is the one the lens is on */
.mari-roleplay-message-row[data-latest] > [data-mari-part="avatar"] button {
  box-shadow:
    0 0 0 1px var(--hal-lens),
    0 0 0 4px var(--hal-g0),
    0 0 0 5px color-mix(in srgb, var(--hal-lens) 55%, var(--hal-line)),
    0 0 18px 2px color-mix(in srgb, var(--hal-lens) 35%, transparent);
}

/* the slab: no bubble, a quiet plate */
.mari-roleplay-message-row [data-mari-part="bubble"] {
  background: var(--hal-slab);
  border: 1px solid var(--hal-line-soft);
  border-radius: var(--hal-r);
  box-shadow: none;
  --tw-ring-shadow: 0 0 #0000;
  color: var(--hal-text);
  max-width: 100%;
}
.mari-roleplay-message-row.mari-message-user [data-mari-part="bubble"] {
  background: var(--hal-slab-user);
  border-color: var(--hal-line);
  border-style: solid;
  align-self: flex-start;
}
.mari-roleplay-message-row [data-mari-part="bubble"] > div {
  padding: 0.7rem 1.15rem 0.9rem;
}
/* connector from spine to slab */
.mari-roleplay-message-row .mari-roleplay-message-body::before {
  content: "";
  position: absolute;
  left: -1rem;
  top: 1.15rem;
  width: 1rem;
  height: 1px;
  background: var(--hal-spine);
}
.mari-roleplay-message-row[data-latest] .mari-roleplay-message-body::before {
  background: linear-gradient(90deg, var(--hal-lens), var(--hal-spine));
}

/* readout line: index · NAME · time */
:root {
  --mari-msg-head-rule: 1px solid var(--hal-line-soft);
}
[data-mari-part="message"] [data-mari-part="header"] .mari-message-name {
  font-family: var(--mari-font-ui);
  font-weight: 600;
  font-size: 0.72rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--hal-text);
}
.mari-roleplay-message-row [data-mari-part="header"] {
  counter-reset: halmsg var(--mari-msg-index);
  gap: 0.6rem;
  padding-bottom: 0.4rem;
  margin-bottom: 0.55rem;
}
.mari-roleplay-message-row [data-mari-part="header"]::before {
  content: counter(halmsg, decimal-leading-zero);
  font-family: var(--hal-mono);
  font-size: 0.68rem;
  color: var(--hal-dim);
  letter-spacing: 0.04em;
}
[data-mari-part="time"] {
  font-family: var(--hal-mono);
  font-size: 0.68rem;
  letter-spacing: 0.02em;
}

/* text */
.mari-roleplay-message-row .mari-message-content {
  color: var(--hal-text);
}
.mari-roleplay-message-row .mari-message-content em,
.mari-roleplay-message-row .mari-message-content i {
  color: var(--hal-muted);
}
[data-mari-part="dialogue"] {
  color: var(--mari-dialogue-color);
}
.mari-message-content hr {
  border: 0;
  height: 11px;
  margin: 1.1em auto;
  width: min(14rem, 60%);
  background:
    radial-gradient(circle, var(--hal-lens) 0 1.5px, transparent 2px) center / 11px 11px no-repeat,
    radial-gradient(circle, transparent 0 4px, var(--hal-line) 4.5px 5px, transparent 5.5px) center / 11px 11px no-repeat,
    linear-gradient(var(--hal-line), var(--hal-line)) left center / calc(50% - 10px) 1px no-repeat,
    linear-gradient(var(--hal-line), var(--hal-line)) right center / calc(50% - 10px) 1px no-repeat;
}

/* conversation: the same spine through the avatar column */
[data-mari-part="message"] [data-component="ConversationMessage.Content"] > [data-mari-part="avatar"] {
  position: relative;
}
[data-mari-part="message"] [data-component="ConversationMessage.Content"] > [data-mari-part="avatar"]::before {
  content: "";
  position: absolute;
  left: 50%;
  top: -0.5rem;
  bottom: -0.5rem;
  width: 1px;
  background: var(--hal-spine);
}
[data-mari-part="message"] [data-component="ConversationMessage.Content"] > [data-mari-part="avatar"] button {
  z-index: 1;
  width: 2.1rem;
  height: 2.1rem;
  margin: 0 auto;
  box-shadow:
    0 0 0 1px var(--hal-line),
    0 0 0 3px var(--hal-g0),
    0 0 0 4px var(--hal-spine);
}

/* user readout reads left to right like every other entry */
.mari-roleplay-message-row.mari-message-user [data-mari-part="header"] {
  flex-direction: row;
  justify-content: flex-start;
}

/* phone (no avatar column): the spine runs just left of the slabs with a ring node per entry */
@media (max-width: 767px) {
  :root[data-overhaul="mobile"] .mari-roleplay-message-row .mari-roleplay-message-body {
    position: relative;
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row {
    padding-left: 1.3rem;
    padding-bottom: 0.9rem;
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row .mari-roleplay-message-body::before {
    content: "";
    position: absolute;
    left: -0.8rem;
    top: 0;
    bottom: -0.9rem;
    width: 1px;
    height: auto;
    background: var(--hal-spine);
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row[data-latest] .mari-roleplay-message-body::before {
    background: var(--hal-spine);
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row .mari-roleplay-message-body::after {
    content: "";
    position: absolute;
    left: calc(-0.8rem - 4.5px);
    top: 0.95rem;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--hal-g0);
    box-shadow: inset 0 0 0 1px var(--hal-muted);
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row.mari-message-user .mari-roleplay-message-body::after {
    box-shadow: inset 0 0 0 1px var(--hal-dim);
    transform: scale(0.75);
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row[data-latest] .mari-roleplay-message-body::after {
    background: radial-gradient(circle, #fff3e2 0 16%, #ffb08f 38%, #ff5a2a 62%, #3a1206 76%);
    box-shadow: 0 0 0 2px var(--hal-g0), 0 0 0 3px color-mix(in srgb, var(--hal-lens) 50%, transparent), 0 0 10px color-mix(in srgb, var(--hal-lens) 45%, transparent);
  }
  :root[data-overhaul="mobile"]:is([data-phone-chat-avatars="mini"], [data-phone-chat-avatars="off"]) .mari-roleplay-message-row [data-mari-part="bubble"] > div {
    padding: 0.6rem 0.9rem 0.75rem;
  }
}

/* ===================== COMPOSER · the console ===================== */
[data-mari-part="composer"] > div:first-child,
[data-mari-part="composer"] .marinara-chat-input-shell {
  border-radius: var(--hal-r);
  border: 1px solid var(--hal-line);
  background:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) left top / 100% 6px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) left top / 100% 3px no-repeat,
    var(--hal-brushed) left top / 1024px 100% repeat-x,
    var(--hal-g1);
  box-shadow: var(--hal-shadow);
}
[data-mari-part="composer"] textarea {
  font-family: var(--mari-font-chat);
  color: var(--hal-text);
}
[data-mari-part="composer"] textarea::placeholder {
  color: var(--hal-dim);
  letter-spacing: 0.02em;
}
:root {
  --mari-icon-send: var(--hal-iris-key);
}
[data-mari-part="composer"] button[aria-label="Send"] {
  border-radius: 50%;
  background: transparent;
}
[data-mari-part="composer"] button[aria-label="Send"] svg {
  width: 2rem;
  height: 2rem;
}
@keyframes hal-breathe {
  0%, 100% { opacity: 0.82; }
  50% { opacity: 1; }
}

/* ===================== SIDEBAR · a hairline index ===================== */
[data-chat-row] {
  border-radius: var(--hal-r);
}
[data-chat-row][data-selected="true"] {
  background: var(--hal-g2);
  box-shadow: inset 0 0 0 1px var(--hal-line);
}

/* ===================== HOME · instrument modules ===================== */
[data-mari-part="home-widget"] {
  box-shadow: none;
  background:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) 0 0 / 100% 6px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) 0 0 / 100% 3px no-repeat,
    var(--mari-home-widget-bg);
}
.mari-home-widget::before {
  box-shadow: none;
}
[data-mari-part="home-widget-eyebrow"] {
  font-family: var(--hal-mono);
  letter-spacing: 0.16em;
}
[data-mari-part="home-widget-eyebrow"]::before {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 0.55em;
  border-radius: 50%;
  vertical-align: 0.05em;
  background: radial-gradient(circle, #fff3e2 0 18%, #ffb08f 40%, #ff5a2a 66%, transparent 74%);
}
:root[data-overhaul] .mari-home-hero h1 {
  font-family: "Iris Display", var(--mari-font-ui);
  font-weight: 300;
  letter-spacing: 0;
}
:root[data-overhaul] .mari-home-hero h1::before {
  content: "";
  display: inline-block;
  width: 0.78em;
  height: 0.78em;
  margin-right: 0.32em;
  vertical-align: -0.06em;
  border-radius: 50%;
  background: var(--hal-iris) center / contain no-repeat;
}
[data-mari-part="home-widget-title"] {
  font-weight: 300;
  letter-spacing: 0.005em;
}

/* ===================== DIALOGS + WINDOWS ===================== */
.mari-window,
[role="dialog"] {
  border-radius: var(--hal-r);
}

/* ===================== GAME · narration is a log slab on a lens node ===================== */
[data-mari-part="message"][data-game-narration] {
  border-radius: var(--hal-r);
  background: var(--hal-slab);
  border: 1px solid var(--hal-line);
  box-shadow: var(--hal-shadow);
  backdrop-filter: none;
  position: relative;
  padding-left: 1.6rem;
}
[data-mari-part="message"][data-game-narration]::before {
  content: "";
  position: absolute;
  left: 0.55rem;
  top: 0.95rem;
  bottom: 0.9rem;
  width: 1px;
  background: var(--hal-spine);
}
[data-mari-part="message"][data-game-narration]::after {
  content: "";
  position: absolute;
  left: calc(0.55rem - 4.5px);
  top: 0.75rem;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff3e2 0 16%, #ffb08f 38%, #ff5a2a 62%, #3a1206 76%);
  box-shadow: 0 0 0 2px var(--hal-slab), 0 0 8px color-mix(in srgb, var(--hal-lens) 45%, transparent);
}
[data-mari-part="message"][data-game-narration] > div:first-child > span {
  border-radius: 2px;
  background: transparent;
  padding: 0;
  font-family: var(--hal-mono);
  font-weight: 400;
  letter-spacing: 0.16em;
  color: var(--hal-muted);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  border-radius: 2px;
  background: transparent;
  border-color: var(--hal-line-soft);
  color: var(--hal-text);
  font-family: var(--mari-font-chat);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose > div:first-child {
  line-height: 1.65;
}
[data-mari-part="game-tools"] button,
[data-mari-part="game-tools-row"] button {
  border-radius: var(--hal-r);
}
[data-mari-part="game-hud"] > * > *,
[data-mari-part="game-hud"] [data-tour="game-map"] {
  border-radius: var(--hal-r);
}
[data-mari-part="game-hud"] [data-tour="game-map"] {
  background: var(--hal-slab);
  border: 1px solid var(--hal-line);
}
:root {
  --mari-game-combat-bg: transparent;
  --mari-game-combat-bg-hover: rgba(255, 174, 98, 0.08);
  --mari-game-combat-border: rgba(255, 174, 98, 0.6);
  --mari-game-combat-text: #ffc58a;
}
:root[data-theme="light"] {
  --mari-game-combat-bg: transparent;
  --mari-game-combat-bg-hover: rgba(178, 106, 20, 0.08);
  --mari-game-combat-border: rgba(178, 106, 20, 0.7);
  --mari-game-combat-text: #7d4a0e;
}
.mari-window-bubble {
  border-radius: 50%;
}

/* ===================== ONE SHAPE: 3px instrument plates ===================== */
.ov-new-pill, .ov-chip-btn, .ov-tag, .ov-btn, .ov-addchip, .ov-select, .ov-pill, .ov-seg, .ov-seg button,
.ov-kit-more, .ov-card__chat, .ov-home-hero-actions .ov-btn, .ov-savebtn, .ov-edbtn, .ov-search,
.ov-gpane__chips span, .ov-gset--tools > button, .ov-sched__bulk button, .ov-mari-assist, .ov-thought-btn,
.ov-classic__edit, .ov-classic__btn, .ov-swipe-chip, .ov-tagpop__search, .ov-tab__count, .ov-icon-btn,
.ov-text-btn, .ov-sideswitch, .ov-sideswitch__btn, .mari-chrome-control, .mari-chrome-segmented, .mari-chrome-segmented button,
:root[data-overhaul] [data-dialog-action], .ov-gallery__tools > .ov-search {
  border-radius: var(--hal-r);
}
.ov-seg button {
  border-radius: 2px;
}
.ov-home-modes .mari-chrome-control {
  border-radius: 3px !important;
}
/* the primary action is a pale ceramic key, not a coloured blob */
.ov-btn--primary, .ov-new-pill, .ov-savebtn {
  background: var(--primary);
  color: var(--primary-foreground);
  border-color: transparent;
  box-shadow: none;
}

/* ===================== PAGES · readout header with a ruler ===================== */
[data-mari-part="page"] {
  --hal-page-pad: 0;
}
[data-mari-part="page-title"] {
  font-size: clamp(1.7rem, 2.4vw, 2.25rem);
  line-height: 1.1;
  color: var(--hal-text);
}
[data-mari-part="page-title"]::before,
.ov-edhead__title::before,
.mari-window__title::before {
  content: "";
  display: inline-block;
  flex: none;
  width: 0.78em;
  height: 0.78em;
  margin-right: 0.4em;
  vertical-align: -0.08em;
  border-radius: 50%;
  background: var(--hal-iris) center / contain no-repeat;
}
.ov-gallery__head {
  padding-bottom: 0.85rem;
  background:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) left bottom / 100% 7px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) left bottom / 100% 4px no-repeat,
    linear-gradient(var(--hal-line), var(--hal-line)) left bottom / 100% 1px no-repeat;
}
/* catalogue numbering, like the message readout */
.ov-gallery__grid {
  counter-reset: halcard;
}
.ov-card {
  counter-increment: halcard;
  border-radius: var(--hal-r);
}
.ov-card__art {
  border-radius: var(--hal-r);
  box-shadow: inset 0 0 0 1px var(--hal-line);
}
.ov-card__name::before {
  content: counter(halcard, decimal-leading-zero);
  font-family: var(--hal-mono);
  font-weight: 400;
  font-size: 0.7rem;
  color: var(--hal-dim);
  margin-right: 0.5em;
  letter-spacing: 0.04em;
}
.ov-card__tags {
  font-family: var(--hal-mono);
  font-size: 0.7rem;
  letter-spacing: 0.01em;
}
.ov-card__tokens {
  font-family: var(--hal-mono);
  border-radius: 2px;
}

/* fields are plates too */
[data-mari-part="page"] :is(input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"]), textarea, select),
[role="dialog"] :is(input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"]), textarea, select),
.ov-addchip,
:is([data-mari-part="page"], .mari-window, .mari-drawer, [role="dialog"], [data-component="RightPanelDesktop"]) button.rounded-full:not([role="switch"], :has(> img)) {
  border-radius: var(--hal-r);
}
/* editor head: same ruler and lens as every page title */
[data-component="OverhaulEditorHead"] {
  background:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) left bottom / 100% 7px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) left bottom / 100% 4px no-repeat,
    linear-gradient(var(--hal-line), var(--hal-line)) left bottom / 100% 1px no-repeat;
}
[data-component="OverhaulEditorHead"] h1,
[data-component="OverhaulEditorHead"] h2 {
  font-family: "Iris Display", var(--mari-font-ui);
  font-weight: 300;
}
[data-mari-part="page"] header.ov-settings__head,
[data-mari-part="page"] header:not(.ov-gallery__head, .ov-settings__head):has(> [data-mari-part="page-title"]) {
  background:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) left bottom / 100% 7px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) left bottom / 100% 4px no-repeat;
  padding-bottom: 0.8rem;
}

/* ===================== SIDEBAR · the chat list is a spine of nodes ===================== */
.ov-sideswitch {
  background: var(--hal-g1);
  box-shadow: inset 0 0 0 1px var(--hal-line-soft);
}
.ov-sideswitch__btn.is-on {
  background: var(--hal-g3);
  color: var(--hal-text);
  box-shadow: inset 0 -2px 0 var(--hal-lens);
}
[data-chat-row] {
  border-radius: var(--hal-r);
  --tw-ring-shadow: 0 0 #0000;
  box-shadow: none;
}
[data-chat-row]::before {
  content: "";
  position: absolute;
  left: calc(0.75rem + 0.875rem - 0.5px);
  top: -0.25rem;
  bottom: -0.25rem;
  width: 1px;
  background: var(--hal-spine);
  z-index: 0;
  pointer-events: none;
}
[data-chat-row] > .relative.flex-shrink-0 {
  z-index: 1;
}
[data-chat-row] > .relative.flex-shrink-0 span.overflow-hidden {
  border-radius: 50%;
  box-shadow: 0 0 0 1px var(--hal-line), 0 0 0 3px var(--hal-g0);
}
[data-chat-row][data-selected="true"] {
  background: var(--hal-g2);
  box-shadow: inset 0 0 0 1px var(--hal-line);
}
[data-chat-row][data-selected="true"] > .relative.flex-shrink-0 span.overflow-hidden {
  box-shadow: 0 0 0 1px var(--hal-lens), 0 0 0 3px var(--hal-g2), 0 0 10px 1px color-mix(in srgb, var(--hal-lens) 40%, transparent);
}
[data-chat-row] .mari-chrome-accent-progress {
  display: none;
}
.mari-chat-sidebar .mari-chrome-segmented {
  background: var(--hal-g1);
}
/* Library navigation: a numbered index, the open page marked by the lens */
:root[data-overhaul] .ov-libnav__item {
  padding-left: 1.1rem;
}
:root[data-overhaul] .ov-libnav__item.is-on::before {
  left: 0.3rem;
  right: auto;
  top: 50%;
  bottom: auto;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff3e2 0 18%, #ffb08f 40%, #ff5a2a 70%);
  box-shadow: 0 0 6px color-mix(in srgb, var(--hal-lens) 60%, transparent);
}

/* ===================== DIALOGS, POPOVERS, MENUS · modules ===================== */
.mari-window,
[role="dialog"],
[role="alertdialog"] {
  border-radius: var(--hal-r);
  box-shadow: var(--hal-shadow);
}
[role="dialog"]:not([data-mari-part]) {
  border-color: var(--hal-line);
}
[role="menu"],
[role="listbox"],
[data-radix-popper-content-wrapper] > * {
  border-radius: var(--hal-r);
  border-color: var(--hal-line);
  box-shadow: var(--hal-shadow);
}
[role="menuitem"],
[role="option"] {
  border-radius: 2px;
}

/* ===================== ONE SLAB on phone + tablet =====================
   Where the readout sits outside the bubble (phone, tablet portrait), the
   readout and the body join into one 3px plate with only the hairline between. */
.mari-roleplay-message-row:has(> .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"]) .mari-roleplay-message-body {
  gap: 0;
  align-items: stretch;
}
.mari-roleplay-message-row [data-mari-part="header"][data-placement="outside"] {
  align-self: stretch;
  margin: 0 !important;
  padding: 0.5rem 0.9rem 0.42rem;
  border: 1px solid var(--hal-line-soft);
  border-bottom: 1px solid var(--hal-line-soft);
  border-radius: 3px 3px 0 0 !important;
  background: var(--mari-pinned-speaker-bg);
  box-shadow: 0 -1px 0 var(--hal-g0);
}
.mari-roleplay-message-row.mari-message-user [data-mari-part="header"][data-placement="outside"] {
  border-color: var(--hal-line);
  border-bottom-color: var(--hal-line-soft);
}
.mari-roleplay-message-row:has(> .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"]) [data-mari-part="bubble"] {
  align-self: stretch;
  max-width: 100%;
  border-top: 0;
  border-radius: 0 0 3px 3px !important;
}

/* ===================== every control is a 3px plate ===================== */
.mari-chrome-field,
.mari-chrome-sort-field,
.marinara-chat-input-shell,
.ov-cb-io__btn,
.mari-preset-native-select {
  border-radius: 3px !important;
}
:is(.mari-window, .mari-drawer, [data-mari-part="page"], [role="dialog"], [data-component="RightPanelDesktop"], [data-component="ChatSidebar"], [data-component="OnboardingTutorial.Card"]) :is(button, a, select, input, textarea, label, span:not(:empty)):is(.rounded, .rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl):not([role="switch"], [role="switch"] *, span.overflow-hidden, .mari-drawer__count, .mari-mini-avatar, [aria-label="Show help"], [data-settings-switch-track], [data-settings-switch-thumb]),
:is(.mari-window, .mari-drawer, [data-mari-part="page"], [role="dialog"], [data-component="RightPanelDesktop"], [data-component="ChatSidebar"], [data-component="OnboardingTutorial.Card"]) :is(button, a, label, span:not(:empty)).rounded-full:not([role="switch"], [role="switch"] *, .mari-drawer__count, .mari-mini-avatar, [aria-label="Show help"], [data-settings-switch-track], [data-settings-switch-thumb]):not(:has(> img)) {
  border-radius: 3px !important;
}
/* fields: one 1px hairline, no doubled ring */
[data-mari-part="page"] textarea.ring-1,
[role="dialog"] textarea.ring-1,
.mari-window textarea.ring-1 {
  box-shadow: none !important;
  border: 1px solid var(--hal-line);
}

/* switches: a 3px track with a small lens for a knob (off: a grey ring, on: lit) */
.ov-switch {
  border-radius: 3px !important;
  background: var(--hal-switch-off);
  box-shadow: inset 0 0 0 1px var(--hal-line), inset 0 0 0 3px var(--hal-switch-off), inset 0 1px 3px rgba(0, 0, 0, 0.25);
}
.ov-switch > span {
  border-radius: 50%;
  background: var(--hal-knob);
  box-shadow: 0 0 0 1px var(--hal-line);
}
.ov-switch.is-on {
  background: var(--hal-g3);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hal-lens) 45%, var(--hal-line));
}
.ov-switch.is-on > span {
  background: radial-gradient(circle, #fff3e2 0 18%, #ffb08f 40%, #ff5a2a 66%, #3a1206 80%);
  box-shadow: 0 0 6px color-mix(in srgb, var(--hal-lens) 50%, transparent);
}
[data-settings-switch-track] {
  border-radius: 3px !important;
  background: var(--hal-switch-off) !important;
  box-shadow: inset 0 0 0 1px var(--hal-line), inset 0 1px 3px rgba(0, 0, 0, 0.25);
}
[data-settings-switch-thumb] {
  border-radius: 50% !important;
  background: var(--hal-knob) !important;
  box-shadow: 0 0 0 1px var(--hal-line) !important;
}
[data-settings-switch-track][data-checked] {
  background: var(--hal-g3) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hal-lens) 45%, var(--hal-line));
}
[data-settings-switch-track][data-checked] [data-settings-switch-thumb] {
  background: radial-gradient(circle, #fff3e2 0 18%, #ffb08f 40%, #ff5a2a 66%, #3a1206 80%) !important;
  box-shadow: 0 0 6px rgba(255, 106, 61, 0.5) !important;
}
/* segmented choice: the active segment carries the lens underline, like a top-bar tab */
.ov-seg button.is-on {
  background: var(--hal-g2);
  color: var(--hal-text);
  box-shadow: inset 0 -2px 0 var(--hal-lens);
}

/* ===================== window + drawer titles: lens-led, ruled ===================== */
.mari-window__title {
  font-family: "Iris Display", var(--mari-font-ui);
  font-weight: 300;
  font-size: 1.15rem;
  letter-spacing: 0.005em;
  text-transform: none;
  color: var(--hal-text);
  display: inline-flex;
  align-items: center;
}
.mari-window .mari-window__title-row {
  background-image:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px),
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px);
  background-size: 100% 6px, 100% 3px;
  background-position: left bottom, left bottom;
  background-repeat: no-repeat;
}
.ov-edhead__title {
  font-family: "Iris Display", var(--mari-font-ui);
  font-weight: 300;
}
/* tutorial card: ruler along the top, lens-led title */
[data-component="OnboardingTutorial.Card"] {
  border-radius: 3px !important;
  background-image:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px),
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px);
  background-size: 100% 6px, 100% 3px;
  background-repeat: no-repeat;
}
[data-component="OnboardingTutorial.Card"] h3 {
  font-family: "Iris Display", var(--mari-font-ui);
  font-weight: 300;
  font-size: 1.1rem;
}
[data-component="OnboardingTutorial.Card"] h3::before {
  content: "";
  display: inline-block;
  width: 0.8em;
  height: 0.8em;
  margin-right: 0.4em;
  vertical-align: -0.08em;
  background: var(--hal-iris) center / contain no-repeat;
}

/* ===================== CONVERSATION · the same log, lighter ===================== */
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="message"] {
  position: relative;
  padding-block: 0.3rem;
}
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="message"]::before {
  content: "";
  position: absolute;
  left: calc(1rem + 1.25rem - 0.5px);
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--hal-spine);
  pointer-events: none;
}
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="message"] [data-component="ConversationMessage.Content"] > [data-mari-part="avatar"]::before {
  display: none;
}
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="message"] [data-component="ConversationMessage.Content"] > [data-mari-part="avatar"] button {
  border-radius: 50%;
  box-shadow:
    0 0 0 1px var(--hal-line),
    0 0 0 3px var(--hal-g0),
    0 0 0 4px var(--hal-spine);
}
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="message"][data-latest] [data-component="ConversationMessage.Content"] > [data-mari-part="avatar"] button {
  box-shadow:
    0 0 0 1px var(--hal-lens),
    0 0 0 3px var(--hal-g0),
    0 0 0 4px color-mix(in srgb, var(--hal-lens) 55%, var(--hal-line)),
    0 0 14px 1px color-mix(in srgb, var(--hal-lens) 35%, transparent);
}
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="header"] {
  counter-reset: halmsg var(--mari-msg-index);
}
.mari-chat-area[data-chat-mode="conversation"] [data-mari-part="header"]::before {
  content: counter(halmsg, decimal-leading-zero);
  font-family: var(--hal-mono);
  font-size: 0.68rem;
  color: var(--hal-dim);
  letter-spacing: 0.04em;
  order: -1;
}
/* the day divider reads like the scene break: TODAY on a hairline with a small lens */
.mari-chat-area[data-chat-mode="conversation"] div.my-4.items-center > div.flex-1.border-t {
  border-color: var(--hal-line);
}
.mari-chat-area[data-chat-mode="conversation"] .mari-conversation-transcript-chrome-text {
  font-family: var(--hal-mono);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--hal-muted);
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
}
.mari-chat-area[data-chat-mode="conversation"] div.flex-1 + .mari-conversation-transcript-chrome-text::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff3e2 0 16%, #ffb08f 36%, #ff5a2a 56%, transparent 62%);
  box-shadow: 0 0 0 3px var(--hal-g0), 0 0 0 4px var(--hal-line);
}

/* ===================== HOME · circles, one key size, mono footer ===================== */
.ov-recent__avatar {
  border-radius: 50% !important;
  box-shadow: 0 0 0 1px var(--hal-line), 0 0 0 3px var(--hal-g1), 0 0 0 4px var(--hal-spine);
}
.ov-recent__all {
  justify-content: flex-end;
  text-align: right;
  font-family: var(--hal-mono);
  font-size: 0.7rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--hal-muted);
  border-radius: 3px;
}
.ov-recent__all::after {
  content: "\2192";
  margin-left: 0.6em;
  letter-spacing: 0;
}
/* the module keeps its grid size; the list docks its footer to the bottom edge */
.mari-home-widget--recent ul:has(.ov-recent__all) {
  display: flex;
  flex-direction: column;
  min-height: 100%;
}
.mari-home-widget--recent li:has(> .ov-recent__all) {
  margin-top: auto;
  padding-top: 0.4rem;
  border-top: 1px solid var(--hal-line-soft);
}
/* all five keys: one size, one weight, monochrome icons; only the iris carries colour */
.ov-home-hero-buttons :is(.ov-btn, .mari-chrome-control) {
  height: 34px !important;
  min-height: 34px !important;
  padding: 0 12px !important;
  gap: 7px !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  letter-spacing: 0.01em;
  border: 1px solid var(--hal-line);
  border-radius: 3px !important;
  color: var(--hal-text) !important;
}
.ov-home-modes .mari-chrome-control span:not(:has(svg)) {
  font-size: 14px !important;
  font-weight: 500 !important;
  color: currentColor !important;
}
.ov-home-modes .mari-chrome-control > span {
  width: auto !important;
  height: auto !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: currentColor !important;
  transform: none !important;
}
.ov-home-hero-buttons :is(.ov-btn, .mari-chrome-control) svg {
  width: 16px !important;
  height: 16px !important;
  color: currentColor !important;
}
.ov-home-hero-actions .ov-btn:not(:has(svg))::before {
  content: "";
  width: 16px;
  height: 16px;
  flex: none;
  background: var(--hal-iris) center / contain no-repeat;
}
:root[data-theme="dark"] .ov-home-modes .mari-chrome-control {
  border-color: #2c2e33 !important;
}
:root[data-theme="light"] .ov-home-modes .mari-chrome-control {
  border-color: #c6c8c9 !important;
}
.ov-home-modes .mari-chrome-control svg {
  color: currentColor !important;
}

/* ===================== DAY · graphite instruments in a white bay ===================== */
:root[data-theme="light"] {
  --mari-top-bar-bg:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.2) 0 1px, transparent 1px 64px) left bottom / 100% 7px no-repeat,
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.11) 0 1px, transparent 1px 8px) left bottom / 100% 4px no-repeat,
    linear-gradient(#3a3c41, #3a3c41) left bottom / 100% 1px no-repeat,
    url("theme:brushed-night.webp") left top / 1024px 100% repeat-x,
    #2a2c30;
}
:root[data-theme="light"] [data-mari-part="top-bar"],
:root[data-theme="light"] [data-mari-part="composer"] {
  --hal-text: #eceae6;
  --hal-muted: #b4b3ae;
  --hal-dim: #9a9b9d;
  --hal-line: #3a3c41;
  --hal-line-soft: #33353a;
  --hal-g1: #2a2c30;
  --hal-g2: #34363b;
  --hal-tick: rgba(255, 255, 255, 0.11);
  --hal-tick-strong: rgba(255, 255, 255, 0.2);
  --hal-brushed: url("theme:brushed-night.webp");
  --hal-lens: #ff6a3d;
  --foreground: #eceae6;
  --muted-foreground: #b4b3ae;
  --border: #3a3c41;
  --ov-text: #eceae6;
  --ov-muted: #b4b3ae;
  --ov-dim: #9a9b9d;
  --ov-line: #3a3c41;
  --ov-hover: #34363b;
  --ov-active-bg: #3a3c41;
  --ov-accent: #dedbd4;
  --mari-accent-text: #d9d6cf;
  --mari-chrome-accent: #cfccc5;
  --mari-top-bar-plate: rgba(255, 255, 255, 0.04);
  --mari-top-bar-plate-active: #3a3c41;
  --marinara-chat-chrome-input-border: #3a3c41;
  color: #eceae6;
}
:root[data-theme="light"] [data-mari-part="top-bar"] :is(.ov-tab, .ov-text-btn, .ov-icon-btn, .ovm-icon-btn, .ovm-title, .ovm-stack-btn) {
  color: #eceae6;
}
:root[data-theme="light"] [data-mari-part="composer"] > div:first-child,
:root[data-theme="light"] [data-mari-part="composer"] .marinara-chat-input-shell {
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.2) 0 1px, transparent 1px 64px) left top / 100% 6px no-repeat,
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.11) 0 1px, transparent 1px 8px) left top / 100% 3px no-repeat,
    url("theme:brushed-night.webp") left top / 1024px 100% repeat-x,
    #2a2c30;
  border-color: #3a3c41;
}
:root[data-theme="light"] [data-mari-part="composer"] :is(button, svg) {
  color: #c9c8c3;
}

/* ===================== PHONE TOP BAR · one plate with hairline dividers ===================== */
:root[data-overhaul="mobile"] [data-mari-part="top-bar"] {
  --mari-top-bar-plate: transparent;
  --mari-top-bar-plate-active: transparent;
}
:root[data-overhaul="mobile"] [data-mari-part="top-bar"] :is(.ovm-icon-btn, .ovm-title, .ovm-stack-btn) {
  background: transparent;
  box-shadow: none;
}
/* phones: narrower keys on the right give the chat title room; every key stays */
@media (max-width: 767px) {
  :root[data-overhaul="mobile"] [data-mari-part="top-bar"] :is(.ovm-icon-btn, .ovm-stack-btn) {
    width: 40px !important;
    min-width: 40px !important;
    padding: 0 !important;
  }
}
:root[data-overhaul="mobile"] [data-mari-part="top-bar"] :is(.ovm-icon-btn, .ovm-title, .ovm-stack-btn):not(:first-child)::before {
  content: "";
  position: absolute;
  left: -2px;
  top: 11px;
  bottom: 11px;
  width: 1px;
  background: var(--hal-line);
  pointer-events: none;
}

/* ===================== GAME PANE · ruled header, mono columns ===================== */
.ov-gpane__tabs {
  background-image:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px),
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px),
    linear-gradient(var(--hal-line), var(--hal-line));
  background-size: 100% 6px, 100% 3px, 100% 1px;
  background-position: left bottom;
  background-repeat: no-repeat;
}
.ov-gpane__tabs button.is-on {
  background: transparent;
  color: var(--hal-text);
  box-shadow: inset 0 -2px 0 var(--hal-lens);
}
.ov-gpane__table th {
  font-family: var(--hal-mono);
  font-weight: 400;
  letter-spacing: 0.14em;
  color: var(--hal-dim);
}

/* ===================== storm: the bay dims a little under the storm ===================== */
:root[data-theme][data-mari-weather="storm"] {
  --mari-app-backdrop-layers: linear-gradient(rgba(8, 10, 14, 0.28), rgba(8, 10, 14, 0.28)), var(--hal-bg) left center / cover no-repeat, var(--hal-g0);
}

/* ===================== reduced motion: the lens holds still ===================== */
@media (prefers-reduced-motion: reduce) {
  [data-mari-part="composer"] button[aria-label="Send"] svg,
  :root[data-overhaul] .mari-home-hero h1::before {
    animation: none;
  }
}

/* ===================== round 2 ===================== */
/* Home recent chats: the type sits beside the name as a mono suffix; rows share the module height */
.mari-home-widget--recent .ov-recent__text {
  flex: 0 1 auto;
  min-width: 0;
}
.mari-home-widget--recent .ov-recent__mode {
  margin-left: 0.8rem;
  margin-right: auto;
  padding: 0;
  border: 0;
  background: none;
  font-family: var(--hal-mono);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--hal-dim);
}
.mari-home-widget--recent button:has(> .ov-recent__text) {
  grid-template-columns: auto auto 1fr !important;
}
.mari-home-widget--recent .ov-recent__mode {
  justify-self: start;
}
/* by day the module grid sits on one square rack plate, so no sill shows between modules */
:root[data-theme="light"] .mari-home-feed-grid {
  background: #ebeae7;
  box-shadow: none;
  border-radius: 3px;
}

/* long replies: the slab hugs a 34em text column (about 68 to 72 characters) */
.mari-roleplay-message-row:not(.mari-message-user) [data-mari-part="bubble"] {
  max-width: min(100%, calc(34em + 2.3rem + 2px));
}
.mari-roleplay-message-row:not(.mari-message-user):has(> .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"]) .mari-roleplay-message-body {
  max-width: min(100%, calc(34em + 2.3rem + 2px));
}

/* swipe controls dock into the slab's bottom edge as a mono footer row (touch only:
   with a mouse they wait under the slab, so short slabs carry no empty band) */
@media (hover: none) {
.mari-roleplay-message-body:has(> .ov-rpf--below:not(:empty)) > [data-mari-part="bubble"] > div {
  padding-bottom: 2.3rem;
}
.mari-roleplay-message-body > .ov-rpf--below:not(:empty) {
  position: relative;
  z-index: 2;
  align-self: flex-end;
  margin-top: -2.15rem !important;
  margin-right: 0.7rem;
  margin-bottom: 0.45rem;
  font-family: var(--hal-mono);
  font-size: 0.7rem;
  color: var(--hal-dim);
}
.mari-roleplay-message-body:has(> .ov-rpf--below:not(:empty)) {
  align-items: stretch;
}
}

/* game: the empty chart card is a ruled 3px module with a mono eyebrow */
[data-mari-part="game-hud"] [data-tour="game-map"] {
  position: relative;
  align-items: flex-start !important;
  justify-content: flex-start !important;
  gap: 0.45rem !important;
  padding: 1.55rem 0.8rem 0.75rem !important;
  border-radius: 3px !important;
  border: 1px solid var(--hal-line) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  background:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px) left top / 100% 6px no-repeat,
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) left top / 100% 3px no-repeat,
    var(--hal-slab) !important;
}
[data-mari-part="game-hud"] [data-tour="game-map"]::before {
  content: "CHART";
  position: absolute;
  top: 0.65rem;
  left: 0.8rem;
  padding-left: 0.9em;
  font-family: var(--hal-mono);
  font-size: 0.62rem;
  letter-spacing: 0.2em;
  color: var(--hal-muted);
  background: radial-gradient(circle, #fff3e2 0 14%, #ffb08f 30%, #ff5a2a 48%, transparent 54%) left center / 7px 7px no-repeat;
}
[data-mari-part="game-hud"] [data-tour="game-map"] > span {
  font-size: 0.8rem !important;
  color: var(--hal-text) !important;
}
[data-mari-part="game-hud"] [data-tour="game-map"] .mari-map-generate-control {
  border-radius: 3px !important;
  border: 1px solid var(--hal-line) !important;
  background: transparent !important;
  font-family: var(--hal-mono);
  letter-spacing: 0.08em;
}

/* day instruments: a lifted graphite so they read as instruments, not holes */
:root[data-theme="light"] {
  --mari-top-bar-bg:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.22) 0 1px, transparent 1px 64px) left bottom / 100% 7px no-repeat,
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.12) 0 1px, transparent 1px 8px) left bottom / 100% 4px no-repeat,
    linear-gradient(#4a4d52, #4a4d52) left bottom / 100% 1px no-repeat,
    linear-gradient(rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.09)),
    url("theme:brushed-night.webp") left top / 1024px 100% repeat-x,
    #34363b;
}
:root[data-theme="light"] [data-mari-part="composer"] > div:first-child,
:root[data-theme="light"] [data-mari-part="composer"] .marinara-chat-input-shell {
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.22) 0 1px, transparent 1px 64px) left top / 100% 6px no-repeat,
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.12) 0 1px, transparent 1px 8px) left top / 100% 3px no-repeat,
    linear-gradient(rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.09)),
    url("theme:brushed-night.webp") left top / 1024px 100% repeat-x,
    #34363b;
}

/* ===================== round 3: overlays, switches, Home ===================== */
/* every popover, sheet and wizard is a 3px plate with the one shadow */
.marinara-chat-popover {
  border-radius: 3px !important;
  border-color: var(--hal-line);
  background-color: var(--hal-slab);
  box-shadow: var(--hal-shadow);
  backdrop-filter: none;
}
.marinara-chat-popover :is(button, a, select, input, textarea, label, span:not(:empty), div.rounded-lg, div.rounded-xl):is(.rounded, .rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl):not(:has(> img)) {
  border-radius: 3px !important;
}
/* menus and list popups share the plate */
:is([role="menu"], [role="listbox"]):is(.rounded, .rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl),
:is([role="menu"], [role="listbox"]) :is([role="menuitem"], [role="option"], button):is(.rounded, .rounded-md, .rounded-lg, .rounded-xl) {
  border-radius: 3px !important;
}
/* popover titles: lens-led, light, ruled underneath */
.marinara-chat-popover__header {
  border-bottom-color: var(--hal-line);
  padding-bottom: 0.7rem;
  background-image:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px),
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px);
  background-size: 100% 6px, 100% 3px;
  background-position: left bottom, left bottom;
  background-repeat: no-repeat;
}
.marinara-chat-popover__title {
  font-family: "Iris Display", "Inter", system-ui, sans-serif !important;
  font-weight: 300 !important;
  font-size: 16px !important;
  letter-spacing: 0.005em;
  color: var(--hal-text) !important;
  gap: 0.5rem;
}
.marinara-chat-popover__header .marinara-chat-popover__title::before {
  content: "";
  width: 16px;
  height: 16px;
  flex: none;
  background: var(--hal-iris) center / contain no-repeat;
}
.marinara-chat-popover__subtitle {
  font-size: 0.8rem;
  color: var(--hal-dim);
}
/* the New Conversation / New Game wizard: an 18px title, 14px body */
.mari-chat-setup-wizard .marinara-chat-popover__header {
  padding: 0.85rem 1.25rem 0.95rem;
}
.mari-chat-setup-wizard .marinara-chat-popover__header .marinara-chat-popover__title {
  font-size: 18px !important;
}
.mari-chat-setup-wizard .marinara-chat-popover__title::before {
  width: 18px;
  height: 18px;
}
.mari-chat-setup-wizard h4 {
  font-family: var(--hal-mono);
  font-size: 0.72rem !important;
  font-weight: 500 !important;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--hal-dim) !important;
}
.mari-chat-setup-wizard :is(.marinara-chat-popover__subtitle, .text-xs, p, input, textarea, select, button, label),
.mari-chat-setup-wizard [class*="text-[0.575rem]"] {
  font-size: 14px !important;
}
.mari-chat-setup-wizard .marinara-chat-popover__subtitle {
  color: var(--hal-dim);
  line-height: 1.45;
}
.mari-chat-setup-wizard [class*="text-[0.5625rem]"] {
  font-family: var(--hal-mono);
  font-size: 11px !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.mari-chat-setup-wizard .border-t {
  border-top-color: var(--hal-line);
}
/* step marks: 2px bars, the current one lit */
.mari-chat-setup-wizard button.h-1\.5.rounded-full {
  height: 2px !important;
  border-radius: 0 !important;
  background: var(--hal-line) !important;
}
.mari-chat-setup-wizard button.h-1\.5.rounded-full.w-3 {
  background: var(--hal-text) !important;
  opacity: 0.62;
}
.mari-chat-setup-wizard button.h-1\.5.rounded-full.w-5 {
  background: var(--hal-lens) !important;
}
/* fields inside overlays: one 1px hairline on the plate, no filled tile */
:is(.marinara-chat-popover, [role="dialog"], [data-component="GlobalOmnibar.Panel"]) :is(input, textarea, select, button).ring-1:not([role="switch"]) {
  background-color: transparent;
  box-shadow: none !important;
  border: 1px solid var(--hal-line);
}
:is(.marinara-chat-popover, [role="dialog"]) :is(input, textarea, select).ring-1:focus {
  border-color: var(--hal-lens);
}
/* panels inside the wizard (Customize Parameters and the like) are hairline plates */
.mari-chat-setup-wizard .rounded-lg.border.bg-\[var\(--card\)\] {
  background-color: transparent;
  border-color: var(--hal-line);
}
/* the app's hand-drawn pill switches (wizard, chat options, editors) become the 3px lens switch */
div.rounded-full:is(.h-5, .h-4):is(.w-9, .w-8, .w-7):has(> div.rounded-full.bg-white) {
  border-radius: 3px !important;
  background: var(--hal-switch-off) !important;
  box-shadow: inset 0 0 0 1px var(--hal-line) !important;
}
div.rounded-full:is(.h-5, .h-4):is(.w-9, .w-8, .w-7) > div.rounded-full.bg-white {
  background: var(--hal-switch-off) !important;
  box-shadow: 0 0 0 1px var(--hal-dim) !important;
}
div.rounded-full:is(.h-5, .h-4):is(.w-9, .w-8, .w-7):is(.mari-chat-option-switch--active, :has(> .translate-x-3\.5), :has(> .translate-x-3)) {
  background: var(--hal-g3) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hal-lens) 45%, var(--hal-line)) !important;
}
div.rounded-full:is(.h-5, .h-4):is(.w-9, .w-8, .w-7) > div.rounded-full.bg-white:is(.translate-x-3\.5, .translate-x-3) {
  background: radial-gradient(circle, #fff3e2 0 18%, #ffb08f 40%, #ff5a2a 66%, #3a1206 80%) !important;
  box-shadow: 0 0 6px rgba(255, 106, 61, 0.5) !important;
}

/* Settings and editor switches, off: a light 1px ring on the track colour, never a dark disc */
.ov-switch,
[data-settings-switch-track] {
  box-shadow: inset 0 0 0 1px var(--hal-line) !important;
}
.ov-switch:not(.is-on) > span {
  background: var(--hal-switch-off);
  box-shadow: 0 0 0 1px var(--hal-dim);
}
[data-settings-switch-track]:not([data-checked]) [data-settings-switch-thumb] {
  background: var(--hal-switch-off) !important;
  box-shadow: 0 0 0 1px var(--hal-dim) !important;
}
.ov-switch.is-on {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hal-lens) 45%, var(--hal-line)) !important;
}
[data-settings-switch-track][data-checked] {
  box-shadow: inset 0 0 0 1px rgba(255, 106, 61, 0.45) !important;
}

/* Settings › Visual style: the chosen card is a hairline plate with a lens rule, not a heavy outline */
.mari-chrome-control--card {
  border-width: 1px !important;
  border-color: var(--hal-line) !important;
  outline: none !important;
}
.mari-chrome-control--card[aria-pressed="true"] {
  background-color: var(--hal-slab) !important;
  box-shadow: inset 2px 0 0 var(--hal-lens) !important;
}

/* Ctrl+K: the command palette is an instrument plate */
[data-component="GlobalOmnibar.Panel"] {
  --mari-panel-gradient-start: var(--hal-line);
  --mari-panel-gradient-end: var(--hal-line);
}
[data-component="GlobalOmnibar.Panel"][role="dialog"] {
  border-radius: 3px !important;
  box-shadow: var(--hal-shadow), 0 0 0 1px var(--hal-line);
}
[data-component="GlobalOmnibar.Panel"] > div[aria-hidden="true"]:first-child {
  display: none;
}
[data-component="GlobalOmnibar.Panel"] > header > div.border-b:first-child {
  border-bottom-color: var(--hal-line);
  background-image:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px),
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px);
  background-size: 100% 6px, 100% 3px;
  background-position: left bottom, left bottom;
  background-repeat: no-repeat;
}
[data-component="GlobalOmnibar.Panel"] :is(li[data-command-center-result-row], [data-command-center-media]) {
  --mari-panel-gradient-start: var(--hal-line);
  --mari-panel-gradient-end: var(--hal-line);
}
[data-component="GlobalOmnibar.Panel"] :is(li[data-command-center-result-row], li[data-command-center-result-row] button, [data-omnibar-scope-chip], [data-component="GlobalOmnibar.Filters"] button, .rounded-md, .rounded-lg, .rounded-xl, .rounded-2xl):not([data-media-kind="avatar"]) {
  border-radius: 3px !important;
}
[data-component="GlobalOmnibar.Panel"] [data-command-center-media]:not([data-media-kind="avatar"]) {
  border-radius: 3px !important;
  border-color: var(--hal-line);
  background-color: transparent;
  color: var(--hal-text);
}
[data-component="GlobalOmnibar.Panel"] [data-command-center-media]:not([data-media-kind="avatar"]) svg {
  color: var(--hal-text) !important;
  opacity: 0.72 !important;
}
[data-component="GlobalOmnibar.Panel"] [data-command-center-media][data-media-kind="avatar"] {
  border-color: var(--hal-line);
  background-color: var(--hal-g2);
  color: var(--hal-dim);
}
[data-component="GlobalOmnibar.Panel"] li[data-command-center-result-row] {
  background-color: transparent;
  box-shadow: none;
}
[data-component="GlobalOmnibar.Panel"] li[data-command-center-result-row]:has([data-selected="true"]) {
  background-color: var(--hal-g2);
  box-shadow: inset 2px 0 0 var(--hal-lens), inset 0 0 0 1px var(--hal-line);
}
[data-component="GlobalOmnibar.Panel"] h3 {
  font-family: var(--hal-mono);
  font-weight: 500;
  letter-spacing: 0.14em;
  color: var(--hal-dim);
}
/* scope tabs read like the top-bar tabs: no fill, the lens underline marks the open one */
[data-component="GlobalOmnibar.Panel"] :is([data-omnibar-scope-chip], [data-component="GlobalOmnibar.Filters"] button) {
  background: transparent;
  color: var(--hal-text);
  box-shadow: inset 0 -1px 0 transparent;
}
[data-component="GlobalOmnibar.Panel"] :is([data-omnibar-scope-chip], [data-component="GlobalOmnibar.Filters"] button):focus-visible {
  box-shadow: inset 0 -2px 0 var(--hal-lens);
}
[data-component="GlobalOmnibar.Filters"] button[aria-pressed="true"] {
  background: var(--hal-g2) !important;
  color: var(--hal-text) !important;
  box-shadow: inset 0 -2px 0 var(--hal-lens);
}
[data-component="GlobalOmnibar.Panel"] > footer {
  border-top-color: var(--hal-line);
  font-family: var(--hal-mono);
  font-size: 0.7rem;
  letter-spacing: 0;
  color: var(--hal-dim);
}
[data-component="GlobalOmnibar.Panel"] > footer > span {
  gap: 0.45rem;
  min-width: 0;
}
[data-component="GlobalOmnibar.Panel"] > footer :is(.mari-kbd-hint > span, .mari-kbd-hint:not(:has(> span))) {
  padding: 1px 6px;
  border: 1px solid var(--hal-line);
  border-radius: 3px;
  background: var(--hal-g2);
  color: var(--hal-text);
  white-space: nowrap;
}
[data-component="GlobalOmnibar.Panel"] > footer .mari-kbd-hint:has(> span) {
  gap: 0.45rem;
}

/* toasts (achievements and the rest): a 3px plate with a ruler and a mono eyebrow, the x inside */
[data-sonner-toaster] [data-sonner-toast] {
  border-radius: 3px !important;
  background-color: var(--hal-slab) !important;
  border-color: var(--hal-line) !important;
  box-shadow: 0 18px 36px -20px rgba(0, 0, 0, 0.55) !important;
  background-image:
    repeating-linear-gradient(90deg, var(--hal-tick-strong) 0 1px, transparent 1px 64px),
    repeating-linear-gradient(90deg, var(--hal-tick) 0 1px, transparent 1px 8px) !important;
  background-size: 100% 6px, 100% 3px !important;
  background-position: left top, left top !important;
  background-repeat: no-repeat !important;
  padding: 18px 40px 14px 16px !important;
}
[data-sonner-toaster] [data-sonner-toast] [data-icon] {
  display: none !important;
}
[data-sonner-toaster] [data-sonner-toast] [data-title] {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-family: var(--hal-mono);
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--hal-dim);
}
[data-sonner-toaster] [data-sonner-toast] [data-title]::before {
  content: "";
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: radial-gradient(circle, #fff3e2 0 18%, #ffb08f 40%, #ff5a2a 70%);
  box-shadow: 0 0 6px rgba(255, 106, 61, 0.55);
}
[data-sonner-toaster] [data-sonner-toast] [data-description] {
  margin-top: 0.3rem;
  font-size: 14px;
  color: var(--hal-text);
}
[data-sonner-toaster] [data-sonner-toast] [data-close-button] {
  left: auto !important;
  right: 8px !important;
  top: 8px !important;
  transform: none !important;
  width: 22px !important;
  height: 22px !important;
  border-radius: 3px !important;
  border: 1px solid transparent !important;
  background: transparent !important;
  color: var(--hal-dim) !important;
}

/* Home: the type labels sit in one right-aligned column */
.mari-home-widget--recent button:has(> .ov-recent__text) {
  grid-template-columns: auto minmax(0, 1fr) auto !important;
}
.mari-home-widget--recent .ov-recent__text {
  overflow: hidden;
}
.mari-home-widget--recent .ov-recent__mode {
  justify-self: end;
  margin: 0;
  text-align: right;
}
@media (max-width: 767px) {
  .mari-home-widget--recent button:has(> .ov-recent__text) {
    grid-template-columns: auto minmax(0, 1fr) auto !important;
  }
}
/* the five rows take up the module's spare height, so the footer rule sits close under them */
@media (min-width: 768px) {
  .mari-home-widget--recent li:has(> button > .ov-recent__text) {
    padding-block: 3px;
  }
}
/* Home quick keys by day: an opaque plate and a hairline, so they never fade into the art */
:root[data-theme="light"] .ov-home-hero-buttons :is(.ov-btn, .mari-chrome-control) {
  background: #f4f3f1 !important;
  border-color: #c6c8c9 !important;
}
/* the version tag reads at 4.5:1 on the plate */
.mari-home-hero span[class*="tracking-[0.14em]"] {
  color: var(--hal-dim);
  font-family: var(--hal-mono);
  font-weight: 500;
}
:root[data-theme="light"] .mari-home-hero span[class*="tracking-[0.14em]"] {
  color: #4f555c;
}
@media (min-width: 768px) {
  .ov-home-hero-buttons {
    margin-left: -5px;
  }
}

/* composer: one placeholder line in every mode */
[data-mari-part="composer"] {
  --mari-composer-placeholder: "Speak. I am listening.";
}

/* portrait night glass under fog and storm: a little more light in the pane */
@media (max-aspect-ratio: 4/5) {
  :root[data-theme][data-mari-weather="storm"] {
    --mari-app-backdrop-layers: linear-gradient(rgba(8, 10, 14, 0.1), rgba(8, 10, 14, 0.1)), var(--hal-bg-phone) center top / cover no-repeat, var(--hal-g0);
  }
  :root[data-theme="dark"][data-mari-weather="storm"] {
    --mari-app-backdrop-layers: linear-gradient(rgba(150, 166, 182, 0.09), rgba(150, 166, 182, 0.09)), var(--hal-bg-phone) center top / cover no-repeat, var(--hal-g0);
  }
  :root[data-theme="dark"][data-mari-weather="fog"] {
    --mari-app-backdrop-layers: linear-gradient(rgba(176, 188, 200, 0.2), rgba(176, 188, 200, 0.2)), var(--hal-bg-phone) center top / cover no-repeat, var(--hal-g0);
  }
}

/* ===================== hover (pointer devices only) ===================== */
@media (hover: hover) and (pointer: fine) {
  [data-component="GlobalOmnibar.Panel"] :is([data-omnibar-scope-chip], [data-component="GlobalOmnibar.Filters"] button[aria-pressed="false"]):hover {
    background: transparent;
    box-shadow: inset 0 -1px 0 var(--hal-dim);
  }
  [data-chat-row]:hover {
    background: var(--hal-g2);
  }
}

/* ===================== round 4: performance (quick to settle, battery-light) ===================== */
/* Only the lens breathes, only on mouse and trackpad devices, and only for six slow breaths after it
   appears; touch devices and reduced motion get a still lens. */
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  :root:not([data-marinara-touch-device="true"]) [data-mari-part="composer"] button[aria-label="Send"] svg,
  :root[data-overhaul]:not([data-marinara-touch-device="true"]) .mari-home-hero h1::before {
    animation: hal-breathe 7s ease-in-out 6;
  }
}
/* the plates are opaque, so frosted glass behind them is wasted paint */
:root[data-theme] *,
:root[data-theme] *::before,
:root[data-theme] *::after {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
/* the stock look's ambient decorations are not part of this room: no twinkling stars or cycling
   gradients behind the bay */
.y2k-star,
.y2k-star-md,
.y2k-star-lg,
.mari-home-browser-star {
  display: none !important;
}
.retro-card,
.pulse-glow,
.bunny-glow,
.pastel-gradient,
.mari-logo-gradient-text--active,
.mari-rgb-toggle-track,
.roleplay-hud-scroll-track--active {
  animation: none !important;
}
/* touch screens: nothing loops, and the soft shadows are short */
:root[data-marinara-touch-device="true"] .mari-home-professor-blink,
:root[data-marinara-touch-device="true"] .mari-professor-pixel-scene * {
  animation: none !important;
}
@media (hover: none) {
  .mari-home-professor-blink,
  .mari-professor-pixel-scene * {
    animation: none !important;
  }
  :root[data-theme="dark"] {
    --hal-shadow: 0 10px 18px -12px rgba(0, 0, 0, 0.8);
  }
  :root[data-theme="light"] {
    --hal-shadow: 0 8px 16px -12px rgba(28, 34, 40, 0.34);
  }
  .mari-roleplay-message-row.mari-message-user > [data-mari-part="avatar"] button {
    filter: none;
    opacity: 0.85;
  }
}
:root[data-marinara-touch-device="true"][data-theme="dark"] {
  --hal-shadow: 0 10px 18px -12px rgba(0, 0, 0, 0.8);
}
:root[data-marinara-touch-device="true"][data-theme="light"] {
  --hal-shadow: 0 8px 16px -12px rgba(28, 34, 40, 0.34);
}

/* ===================== round 4: polish ===================== */
/* wizard: the PRESET tag is a 3px plate, field labels speak in the eyebrow's mono voice */
.mari-chat-setup-wizard span.rounded-full:not(:has(> img)) {
  border-radius: 3px !important;
  background: transparent !important;
  box-shadow: inset 0 0 0 1px var(--hal-line) !important;
}
.mari-chat-setup-wizard label.uppercase {
  font-family: var(--hal-mono);
  font-size: 0.72rem !important;
  font-weight: 500 !important;
  letter-spacing: 0.14em;
  color: var(--hal-dim) !important;
}
/* the Random / Dice pick row is a hairline plate with a hairline icon tile */
.mari-chat-setup-wizard div.overflow-hidden.rounded-lg.border {
  background: transparent !important;
  border-color: var(--hal-line) !important;
}
.mari-chat-setup-wizard div.overflow-hidden.rounded-lg.border div.h-7.w-7.rounded-md {
  background: transparent !important;
  color: var(--hal-text) !important;
  box-shadow: inset 0 0 0 1px var(--hal-line) !important;
  border-radius: 3px !important;
}
/* the small title iris needs a little more light on graphite */
:root[data-theme="dark"] .marinara-chat-popover__header .marinara-chat-popover__title::before {
  filter: brightness(1.35) contrast(1.05);
}
/* switches, off: a lens switched off, a fine ring with a dim 2px centre */
.ov-switch:not(.is-on) > span,
[data-settings-switch-track]:not([data-checked]) [data-settings-switch-thumb],
div.rounded-full:is(.h-5, .h-4):is(.w-9, .w-8, .w-7) > div.rounded-full.bg-white:not(.translate-x-3\.5, .translate-x-3) {
  background: radial-gradient(circle closest-side, #8a8d93 0 13%, transparent 17% 62%, #8a8d93 66% 78%, transparent 82%) !important;
  box-shadow: none !important;
}
/* sidebar row preview: a 3px plate, mono speaker labels, a lens rail on the reply */
[data-chat-floating-panel][role="tooltip"] {
  border-radius: 3px !important;
  background-color: var(--hal-slab) !important;
  border-color: var(--hal-line) !important;
  box-shadow: var(--hal-shadow), 0 0 0 1px var(--hal-line);
}
[data-chat-floating-panel][role="tooltip"] span.uppercase {
  font-family: var(--hal-mono);
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  color: var(--hal-dim);
}
[data-chat-floating-panel][role="tooltip"] .text-\[0\.6875rem\] {
  font-size: 13px;
}
[data-chat-floating-panel][role="tooltip"] span[aria-hidden].rounded-full {
  border-radius: 0 !important;
  width: 1px;
  background: var(--hal-line);
}
[data-chat-floating-panel][role="tooltip"] span[aria-hidden].rounded-full.bg-\[var\(--primary\)\]\/60 {
  width: 2px;
  background: var(--hal-lens);
}
/* palette footer: every hint keeps its words; only the long Ctrl+Enter hint gives way */
[data-component="GlobalOmnibar.Panel"] > footer {
  padding-right: 0.75rem;
}
[data-component="GlobalOmnibar.Panel"] > footer > span.mari-kbd-hint {
  min-width: 0;
  overflow: hidden;
}
[data-component="GlobalOmnibar.Panel"] > footer .mari-kbd-hint > span {
  flex: none;
}
[data-component="GlobalOmnibar.Panel"] > footer .mari-kbd-hint > span:nth-child(2):not(:last-child) {
  flex: 0 1 auto;
  min-width: 2.5rem;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Home version tag by day: a small opaque plate, so it reads over the window art on tablets */
:root[data-theme="light"] .mari-home-hero span[class*="tracking-[0.14em]"] {
  color: #4c5157;
  background: #f4f3f1;
  padding: 1px 6px;
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px #c6c8c9;
}
/* decorative blurred glows behind modules are 64px blur filters: costly to paint, invisible on opaque plates */
.pointer-events-none.absolute:is(.blur-xl, .blur-2xl, .blur-3xl) {
  display: none !important;
}
